// La autenticación la hace el propio nodo webhook.
// El calendario lo manda el núcleo desde el YAML (agenda.calendarioId).
// Antes había aquí un mapa clientId -> calendario escrito a mano.

const salida = [];

for (const item of $input.all()) {
  const cuerpo = item.json.body ?? {};

  const calendarId = cuerpo.calendarioId;
  if (!calendarId) {
    throw new Error('La petición no trae calendarioId: ¿núcleo sin desplegar?');
  }

  salida.push({
    json: {
      timeMin: cuerpo.desde,
      timeMax: cuerpo.hasta,
      calendarId
    }
  });
}

return salida;

// Convierte la respuesta de freeBusy al esquema que espera el nucleo.
// NO se filtra nada: ni horario, ni dias de cierre, ni antelacion, ni
// duracion. Eso lo aplica el nucleo, que tiene el YAML y los tests.
// Si la clinica cierra los domingos, mandamos igualmente lo ocupado
// un domingo.

const respuesta = $input.first().json;
const calendarId = $('Comprobar y preparar ocupacion').first().json.calendarId;

const calendario = respuesta.calendars?.[calendarId];

// Si el calendario no existe o no esta compartido, Google NO falla:
// devuelve errors y busy vacio. Sin esta comprobacion diriamos
// "no hay nada ocupado" y el agente propondria citas encima de una
// agenda llena. Es el fallo silencioso mas caro de esta integracion.
if (calendario?.errors) {
  throw new Error('Google devolvio errores para el calendario: ' + JSON.stringify(calendario.errors));
}

if (!calendario) {
  throw new Error('Google no devolvio el calendario ' + calendarId);
}

// toISOString() garantiza el formato con Z. El nucleo rechaza
// desplazamientos tipo +02:00.
const ocupado = (calendario.busy ?? []).map((bloque) => ({
  inicio: new Date(bloque.start).toISOString(),
  fin: new Date(bloque.end).toISOString()
}));

return [{ json: { ocupado } }];

// La autenticación la hace el propio nodo webhook.
// El calendario lo manda el núcleo desde el YAML (agenda.calendarioId).
// Antes había aquí un mapa clientId -> calendario escrito a mano.

const salida = [];

for (const item of $input.all()) {
  const cuerpo = item.json.body ?? {};

  const calendarId = cuerpo.calendarioId;
  if (!calendarId) {
    throw new Error('La petición no trae calendarioId: ¿núcleo sin desplegar?');
  }

  salida.push({
    json: {
      timeMin: cuerpo.inicio,
      timeMax: cuerpo.fin,
      inicio: cuerpo.inicio,
      fin: cuerpo.fin,
      calendarId
    }
  });
}

return salida;

// Solape estricto, la misma semantica que el nucleo:
//   inicio_a < fin_b && inicio_b < fin_a
// Los intervalos que se TOCAN no solapan: 08:00-08:30 y 08:30-09:00
// son compatibles. Con <= devolveriamos libre:false sobre huecos
// perfectamente buenos y el paso 6 no confirmaria nunca.

const respuesta = $input.first().json;
const preparado = $('Comprobar y preparar hueco').first().json;
const calendario = respuesta.calendars?.[preparado.calendarId];

if (calendario?.errors) {
  throw new Error('Google devolvio errores para el calendario: ' + JSON.stringify(calendario.errors));
}

if (!calendario) {
  throw new Error('Google no devolvio el calendario ' + preparado.calendarId);
}

const inicioA = new Date(preparado.inicio).getTime();
const finA = new Date(preparado.fin).getTime();

const solapa = (calendario.busy ?? []).some((bloque) => {
  const inicioB = new Date(bloque.start).getTime();
  const finB = new Date(bloque.end).getTime();
  return inicioA < finB && inicioB < finA;
});

// Booleano JSON de verdad, no la cadena "true".
return [{ json: { libre: !solapa } }];
